def experiment(inputs):
    trials = inputs.get('trials', [])
    results = []
    for trial in trials:
        # Simulate deterministic verification
        valid = trial.get('state') == trial.get('expected_state') and trial.get('proposal') is not None
        results.append(valid)
    return {"measurements": {"transition_accuracy": [1.0 if all(results) else 0.0]}}

