def experiment(inputs):
    trials = inputs.get('trials', [])
    scores = []
    for trial in trials:
        expected = trial.get('expected_state')
        actual = trial.get('state')
        proposal = trial.get('proposal')
        valid = 1.0 if (expected == actual and proposal is not None) else 0.0
        scores.append(valid)
    return {"measurements": {"accuracy": scores}}

def experiment(inputs):
    trials = inputs.get('trials', [])
    results = []
    for t in trials:
        # Verify transition consistency against bounded state model
        v = 1.0 if t.get('transition_valid') == True else 0.0
        results.append(v)
    return {'accuracy': sum(results) / len(results) if len(results) > 0 else 0.0}

def experiment(inputs):
    trials = inputs.get('trials', [])
    if not trials:
        return {'accuracy': 0.0}
    results = []
    for t in trials:
        v = 1.0 if t.get('transition_valid') == True else 0.0
        results.append(v)
    return {'accuracy': sum(results) / len(results)}

def experiment(inputs):
    trials = inputs.get('trials', [])
    if not trials:
        return {'measurements': {'accuracy': [0.0]}}
    results = []
    for t in trials:
        v = 1.0 if t.get('transition_valid') == True else 0.0
        results.append(v)
    return {'measurements': {'accuracy': results}}
